 41	    public boolean canTransitionTo(Xhq12Status newStatus) {
 42	        Set<Xhq12Status> allowedNextStates = ALLOWED_TRANSITIONS.get(this);
 43	        return allowedNextStates != null && allowedNextStates.contains(newStatus);
 44	    }
