174	            case ON_AUCTION -> newStatus == SOLD || newStatus == AUCTION_EXPIRED;
175	            case SELLING -> newStatus == SOLD || newStatus == AUCTION_EXPIRED || newStatus == ON_AUCTION;
176	            case SOLD, AUCTION_EXPIRED, FAILED_INSPECTION -> false;
177	        };
178	    }
