public class Xnd96CommandService {
    private final Xnd96Repository orderItemRepository;
    @Transactional
    public Xnd96 createOrderItem(Xhq12 order, Xcc44 productSize, int price) {
        try {
            if (productSize == null) {
                throw new Xpb58Exception("상품 사이즈 정보가 없습니다.");
            }
            if (price <= 0) {
                throw new Xwn18Exception("주문 항목 가격은 0보다 커야 합니다. 현재 가격: " + price);
            }
            Xnd96 orderItem = Xnd96.builder()
                    .order(order)
                    .productSize(productSize)
                    .quantity(1)
                    .price(price)
                    .build();
            return orderItemRepository.save(orderItem);
        } catch (Exception e) {
            if (e instanceof Xpb58Exception || e instanceof Xwn18Exception) {
                throw e;
            }
            log.error("주문 항목 생성 중 오류 발생: {}", e.getMessage(), e);
            throw new Xxx52Exception("주문 항목 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }
}
